  return (
    <Jumbotron>
      <h1>Soaring Analyst</h1>

      <p>
        A free browser-based flight planning and analysis tool for glider pilots.
      </p>

      <p>
        &copy; 2016 Alistair Green
      </p>

      <ButtonToolbar>
        <LinkContainer to="/task">
          <Button bsStyle="primary">Plan a cross country task </Button>
