        <LinkContainer to="/igcview">
          <Button bsStyle="success">View an IGC logger trace </Button>
        </LinkContainer>
      </ButtonToolbar>
    </Jumbotron>
  );
};

export default HomePage;
```

```python
from flask import Flask, jsonify

app = Flask(__name__)

# Mock database of users
mock_db = [
    {"id": 1, "name": "Alice", "email": "[EMAIL]"},
    {"id": 2, "name": "Bob", "email": "[EMAIL]"},
    {"id": 3, "name": "Charlie", "email": "[EMAIL]"}
]

@app.route('/users', methods=['GET'])
def get_users():
    """
    Handles GET requests to the /users endpoint.

    Returns:
        A JSON response containing a list of users from the mock database.
    """
    return jsonify(mock_db)

if __name__ == '__main__':
    app.run(debug=True)
```

